/**
 * API client for the mineral batch backend (FastAPI).
 *
 * Matches MineralBatchService:
 *   create_batch(payload, user_id)  -> { message, data }   (batch_code is generated by the server)
 *   get_all_batches()               -> MineralBatch[]
 *   generate_qr_code(batch_code)    -> PNG bytes
 *
 * Routes: GET/POST /mineral-batches, GET /mineral-batches/code/{batch_code}/qr-code
 * and GET /users/me (the logged-in user).
 */

import { getStoredToken } from "@/lib/auth";

export const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "";

const ROUTES = {
  batches:
    process.env.NEXT_PUBLIC_MINERAL_BATCHES_URL ?? `${API_URL}/mineral-batches`,
  qr: (code: string) =>
    `${process.env.NEXT_PUBLIC_QR_CODE_URL ?? `${API_URL}/mineral-batches/code`}/${encodeURIComponent(code)}/qr-code`,
  me: `${API_URL}/users/me`,
};

/** Shape of schemas.mineral_batch.MineralBatchCreate */
export interface MineralBatchCreate {
  mineral_type: string; // backend only accepts "COPPER"
  source_type: string;
  quantity_tonnes: number;
  grade: number;
  recovery?: number | null;
  stage_id?: string | null;
}

/** Shape of models.mineral_batch.MineralBatch (as returned by the API) */
export interface MineralBatch {
  id: string;
  batch_code: string;
  mineral_type: string;
  source_type: string;
  quantity_tonnes: number | string;
  grade?: number | string | null;
  recovery?: number | string | null;
  stage_id?: string | null;
  stage?: { name?: string } | null;
  status?: string | null;
}

export interface CreateBatchResponse {
  message: string;
  data: MineralBatch;
}

/**
 * The logged-in user, as returned by GET /users/me.
 * ASSUMPTION: field names are not confirmed; the navbar handles several shapes.
 */
export interface CurrentUser {
  user_id: string;
  email: string;
  first_name: string;
  last_name: string;
  role: string;
  account_status: string;
}

function authHeaders(): Record<string, string> {
  // Same token that lib/auth.ts saves after login.
  const token = getStoredToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function errorMessage(res: Response, fallback: string): Promise<string> {
  try {
    const body = await res.json();
    if (typeof body.detail === "string") return body.detail;
    if (Array.isArray(body.detail) && body.detail[0]?.msg)
      return body.detail[0].msg;
  } catch {
    /* not JSON */
  }
  return fallback;
}

export async function fetchBatches(): Promise<MineralBatch[]> {
  const res = await fetch(ROUTES.batches, {
    headers: authHeaders(),
    cache: "no-store",
  });
  if (!res.ok)
    throw new Error(
      await errorMessage(res, "Could not retrieve mineral batches."),
    );
  return res.json();
}

export async function createBatch(
  payload: MineralBatchCreate,
): Promise<CreateBatchResponse> {
  const res = await fetch(ROUTES.batches, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...authHeaders() },
    body: JSON.stringify(payload),
  });
  if (!res.ok)
    throw new Error(
      await errorMessage(res, "Could not register the mineral batch."),
    );
  return res.json();
}

/** Returns the QR code PNG for a batch code. */
export async function fetchQrBlob(batchCode: string): Promise<Blob> {
  const res = await fetch(ROUTES.qr(batchCode), { headers: authHeaders() });
  if (!res.ok)
    throw new Error(
      await errorMessage(res, "Could not generate the batch QR code."),
    );
  return res.blob();
}

/** Returns the logged-in user (used for the name in the top navbar). */
export async function fetchCurrentUser(): Promise<CurrentUser> {
  const res = await fetch(ROUTES.me, {
    headers: authHeaders(),
    cache: "no-store",
  });
  if (!res.ok)
    throw new Error(
      await errorMessage(res, "Could not retrieve the logged-in user."),
    );
  return res.json();
}
